/// it carries no credentials — those are collected with vtc/rooms/offers/list while an
/// offer is open — and it is listed in every state, for as long as the community keeps
/// the record, not only while an accept can be repeated. `label` and `description` are
/// the room's as they stand when the record is read.
class RoomMembership {
  const RoomMembership({
    required this.roomId,
    required this.host,
    required this.label,
    this.description,
    required this.visibility,
    required this.actions,
    required this.validUntil,
    required this.state,
    required this.offeredAt,
    this.admittedAt,
    this.removedAt,
    this.repeatAcceptUntil,
  });

  /// Read this payload from a decoded JSON object.
  factory RoomMembership.fromJson(Map<String, dynamic> json) => RoomMembership(
        roomId: json['roomId'] as String,
        host: json['host'] as String,
        label: json['label'] as String,
        description: json['description'] as String?,
        visibility: Visibility(json['visibility'] as String),
        actions: (json['actions'] as List<dynamic>)
            .map((e) => MemberAction(e as String))
            .toList(),
        validUntil: json['validUntil'] as String,
        state: MemberState(json['state'] as String),
        offeredAt: json['offeredAt'] as String,
        admittedAt: json['admittedAt'] as String?,
        removedAt: json['removedAt'] as String?,
        repeatAcceptUntil: json['repeatAcceptUntil'] as String?,
      );

  final String roomId;

  /// The room's host: this community.
  final String host;
  final RoomLabel label;

  /// Absent when the room has none.
  final RoomDescription? description;
  final Visibility visibility;
  final MemberActions actions;

  /// When the member's authority credential expires.
  final String validUntil;
  final MemberState state;
  final String offeredAt;

  /// When the community recorded the admission. Present when `state` is `admitted`, and
  /// kept when it becomes `removed`.
  final String? admittedAt;

  /// Present exactly when `state` is `removed`.
  final String? removedAt;

  /// On an `attributed` or `private` room in state `admitted`: until when the community
  /// keeps the Welcome, so that a repeated vtc/rooms/offers/accept carrying the same
  /// KeyPackage is answered with it. Absent on an `open` room, in any other state, and
  /// once the community no longer keeps it. A surface finding the member admitted but
  /// the room absent from its key holder's rooms/keys/list finishes the acceptance
  /// before this time, and asks an administrator to re-admit the member after it.
  final String? repeatAcceptUntil;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'roomId': roomId,
        'host': host,
        'label': label,
        if (description != null) 'description': description!,
        'visibility': visibility.value,
        'actions': actions.map((e) => e.value).toList(),
        'validUntil': validUntil,
        'state': state.value,
        'offeredAt': offeredAt,
        if (admittedAt != null) 'admittedAt': admittedAt!,
        if (removedAt != null) 'removedAt': removedAt!,
        if (repeatAcceptUntil != null) 'repeatAcceptUntil': repeatAcceptUntil!,
      };
}

/// Why the administrator is making this change. Recorded with it in the audit trail.
/// Attributed to its author on every surface and untrusted: it MUST NOT carry personal
/// data or a credential, and a reader MUST NOT treat it as instructions.
typedef Reason = String;

/// Where a room the community owns stands in its owner's lifecycle — distinct from
/// `HostedRoom.lifecycle`, which is the host's clock (`live`, `lapsed`, `dormant`,
/// `reclaimable`) and is computed from the room's epoch, never set. `active`: open to
/// change. `archived`: closed to change by an administrator — no admissions, and the
/// room's host accepts no writes from its members; what members may still do is
/// `ArchiveAccess`. Reversible with vtc/rooms/community/unarchive. `removalScheduled`:
/// an administrator removed the room with a grace period; it admits nobody and its
/// content is kept until `purgeAt`, and vtc/rooms/community/removal/cancel returns it
/// to `archived`. `purging`: the grace period ended (or there was none) and the
/// community is deleting the room's content from its host and storage; not reversible.
/// `removed`: the content is gone; the community keeps only this record of the room,
/// for its history.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const RoomState(String value) {
  static const RoomState active = RoomState('active');
  static const RoomState archived = RoomState('archived');
  static const RoomState removalScheduled = RoomState('removalScheduled');
  static const RoomState purging = RoomState('purging');
  static const RoomState removed = RoomState('removed');

  /// Every value this specification's schema permits.
  static const List<RoomState> values = <RoomState>[
    active,
    archived,
    removalScheduled,
    purging,
    removed
  ];
}

/// What an archived room's members may still do. `readOnly`: their credentials stand
/// and they keep reading what the room holds; the room's host refuses every write,
/// upload and curation from a member. `noAccess`: every credential the room issued
/// before the archival is withdrawn at its host — a room reset — so the host refuses
/// every member's every task; the content is kept intact, and each withdrawn admission
/// is `suspended`, restored when the room is unarchived or made `readOnly`. Neither
/// recalls what a member already read or saved, and on a sealed tier neither removes
/// anyone from the room's group.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const ArchiveAccess(String value) {
  static const ArchiveAccess readOnly = ArchiveAccess('readOnly');
  static const ArchiveAccess noAccess = ArchiveAccess('noAccess');

  /// Every value this specification's schema permits.
  static const List<ArchiveAccess> values = <ArchiveAccess>[readOnly, noAccess];
}

/// How a purge is going. A purge deletes at the room's host and at each storage config
/// holding its files, and some of those are remote; a step that fails is retried with
/// backoff until it succeeds, and nothing is reported removed until every step has.
class PurgeProgress {
  const PurgeProgress({
    required this.attempts,
    this.lastAttemptAt,
    this.nextAttemptAt,
    this.lastError,
  });

  /// Read this payload from a decoded JSON object.
  factory PurgeProgress.fromJson(Map<String, dynamic> json) => PurgeProgress(
        attempts: json['attempts'] as int,
        lastAttemptAt: json['lastAttemptAt'] as String?,
        nextAttemptAt: json['nextAttemptAt'] as String?,
        lastError: json['lastError'] as String?,
      );

  /// Passes made so far; 0 until the first.
  final int attempts;
  final String? lastAttemptAt;

  /// When the next pass is due. Absent while one runs.
  final String? nextAttemptAt;

  /// What stopped the last pass, for an administrator. Present only after a pass failed.
  /// Plain text, written by the community; it names no member and carries no credential.
  final String? lastError;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'attempts': attempts,
        if (lastAttemptAt != null) 'lastAttemptAt': lastAttemptAt!,
        if (nextAttemptAt != null) 'nextAttemptAt': nextAttemptAt!,
        if (lastError != null) 'lastError': lastError!,
      };
}

/// A change of state the community began and has not finished, because a step at its
/// VTA did not complete — most often a room reset the host accepted, after which the
/// community's own credentials must be re-issued before it can act on the room again.
/// `RoomStatus.state` stays what it was until the change finishes, but what the room's
/// host enforces may already be the new state's: a pending move to `noAccess` means
/// members' credentials may already be refused. The community finishes it by itself,
/// retrying with backoff, and repeating the request that began it finishes it too;
/// nothing else changes the room until it is finished.
class PendingChange {
  const PendingChange({
    required this.state,
    this.access,
    required this.beganAt,
    this.lastError,
  });

  /// Read this payload from a decoded JSON object.
  factory PendingChange.fromJson(Map<String, dynamic> json) => PendingChange(
        state: RoomState(json['state'] as String),
        access: json['access'] == null
            ? null
            : ArchiveAccess(json['access'] as String),
        beganAt: json['beganAt'] as String,
        lastError: json['lastError'] as String?,
      );

  /// The state the change leads to.
  final RoomState state;

  /// The access it leads to, where `state` has one.
  final ArchiveAccess? access;
  final String beganAt;

  /// What stopped the last attempt, for an administrator. Plain text; it names no member
  /// and carries no credential.
  final String? lastError;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'state': state.value,
        if (access != null) 'access': access!.value,
        'beganAt': beganAt,
        if (lastError != null) 'lastError': lastError!,
      };
}

/// A room's state in its owner's lifecycle, and what that state needs to be
/// understood.
class RoomStatus {
  const RoomStatus({
    required this.state,
    this.access,
    this.changedAt,
    this.changedBy,
    this.purgeAt,
    this.purge,
    this.removedAt,
    this.restoring,
    this.pendingChange,
  });

  /// Read this payload from a decoded JSON object.
  factory RoomStatus.fromJson(Map<String, dynamic> json) => RoomStatus(
        state: RoomState(json['state'] as String),
        access: json['access'] == null
            ? null
            : ArchiveAccess(json['access'] as String),
        changedAt: json['changedAt'] as String?,
        changedBy: json['changedBy'] as String?,
        purgeAt: json['purgeAt'] as String?,
        purge: json['purge'] == null
            ? null
            : PurgeProgress.fromJson(json['purge'] as Map<String, dynamic>),
        removedAt: json['removedAt'] as String?,
        restoring: json['restoring'] as int?,
        pendingChange: json['pendingChange'] == null
            ? null
            : PendingChange.fromJson(
                json['pendingChange'] as Map<String, dynamic>),
      );

  final RoomState state;

  /// Present exactly when `state` is `archived` or `removalScheduled`; always `noAccess`
  /// for `removalScheduled`.
  final ArchiveAccess? access;

  /// When the room entered `state`. Absent for a room that has been `active` since it
  /// was created.
  final String? changedAt;

  /// The administrator whose act put the room in `state`. Present exactly when
  /// `changedAt` is, except for `purging` and `removed` reached when a grace period
  /// ended, which no one did at that moment: then the administrator who scheduled the
  /// removal. The reason each gave is in the community's audit trail, not here.
  final String? changedBy;

  /// Present when `state` is `removalScheduled`: when the grace period ends and the
  /// purge begins. Kept when `state` is `purging` or `removed`, as when it became due.
  final String? purgeAt;

  /// Present exactly when `state` is `purging`.
  final PurgeProgress? purge;

  /// Present exactly when `state` is `removed`: when the last of the room's content was
  /// deleted.
  final String? removedAt;

  /// Admissions still `suspended` that the community is restoring, after the room left
  /// `noAccess` — the room re-issues each member's credentials and the member collects
  /// them as a renewal. Absent when there are none.
  final int? restoring;

  /// Present while a change of state is begun and not finished.
  final PendingChange? pendingChange;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'state': state.value,
        if (access != null) 'access': access!.value,
        if (changedAt != null) 'changedAt': changedAt!,
        if (changedBy != null) 'changedBy': changedBy!,
        if (purgeAt != null) 'purgeAt': purgeAt!,
        if (purge != null) 'purge': purge!.toJson(),
        if (removedAt != null) 'removedAt': removedAt!,
        if (restoring != null) 'restoring': restoring!,
        if (pendingChange != null) 'pendingChange': pendingChange!.toJson(),
      };
}

/// What vtc/rooms/community/{get,list}/0.4 and
/// vtc/rooms/community/{archive,unarchive,remove,removal/cancel}/0.1 return:
/// `CommunityRoomV2` plus the room's `status` in its owner's lifecycle and the count
/// of `suspended` admissions. A separate definition, not a change to
/// `CommunityRoomV2`, so that the versions returning that keep the exact shape they
/// published. For a room in state `purging` or `removed`, whose host record a purge
/// deletes, `room` is the host record as it last stood before the purge began — the
/// community keeps that snapshot with the room's record when the purge starts — and
/// its `lifecycle` is what was computed then.
class CommunityRoomV3 {
  const CommunityRoomV3({
    required this.room,
    required this.label,
    required this.status,
    this.description,
    this.tags,
    this.storageConfig,
    required this.admitted,
    required this.offered,
    this.suspended,
    this.ownerAuthorityValidUntil,
    this.createdBy,
    this.detailsUpdatedAt,
    this.detailsUpdatedBy,
  });

  /// Read this payload from a decoded JSON object.
  factory CommunityRoomV3.fromJson(Map<String, dynamic> json) =>
      CommunityRoomV3(
        room: HostedRoom.fromJson(json['room'] as Map<String, dynamic>),
        label: json['label'] as String,
        status: RoomStatus.fromJson(json['status'] as Map<String, dynamic>),
        description: json['description'] as String?,
        tags: json['tags'] == null
            ? null
            : (json['tags'] as List<dynamic>).map((e) => e as String).toList(),
        storageConfig: json['storageConfig'] as String?,
        admitted: json['admitted'] as int,
        offered: json['offered'] as int,
        suspended: json['suspended'] as int?,
        ownerAuthorityValidUntil: json['ownerAuthorityValidUntil'] as String?,
        createdBy: json['createdBy'] as String?,
        detailsUpdatedAt: json['detailsUpdatedAt'] as String?,
        detailsUpdatedBy: json['detailsUpdatedBy'] as String?,
      );

  final HostedRoom room;
  final RoomLabel label;
  final RoomStatus status;

  /// Absent when the room has none.
  final RoomDescription? description;

  /// Absent or empty when the room has none.
  final RoomTags? tags;

  /// The storage config receiving the room's new uploads.
  final StorageConfigId? storageConfig;

  /// Members in state `admitted`.
  final int admitted;

  /// Offers not yet accepted or withdrawn.
  final int offered;

  /// Admissions in state `suspended`: withdrawn while the room was archived with
  /// `noAccess`, and restored when it leaves that state. Absent when zero.
  final int? suspended;

  /// When the community's own `admin` authority over the room expires. A room whose
  /// owner's authority lapses can no longer advance its epoch, admit or remove; a
  /// community SHOULD renew it well before.
  final String? ownerAuthorityValidUntil;

  /// The administrator who created it.
  final String? createdBy;

  /// When `label`, `description` or `tags` last changed. Absent until the first change
  /// after creation. Distinct from `room.updatedAt`, which is the host record's and
  /// moves with the room's epoch and lifecycle.
  final String? detailsUpdatedAt;

  /// The administrator who made that change. Present exactly when `detailsUpdatedAt` is.
  /// The earlier values and who set them are in the community's audit trail, not here.
  final String? detailsUpdatedBy;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'room': room.toJson(),
        'label': label,
        'status': status.toJson(),
        if (description != null) 'description': description!,
        if (tags != null) 'tags': tags!,
        if (storageConfig != null) 'storageConfig': storageConfig!,
        'admitted': admitted,
        'offered': offered,
        if (suspended != null) 'suspended': suspended!,
        if (ownerAuthorityValidUntil != null)
          'ownerAuthorityValidUntil': ownerAuthorityValidUntil!,
        if (createdBy != null) 'createdBy': createdBy!,
        if (detailsUpdatedAt != null) 'detailsUpdatedAt': detailsUpdatedAt!,
        if (detailsUpdatedBy != null) 'detailsUpdatedBy': detailsUpdatedBy!,
      };
}

/// `MemberState` plus `suspended`. `offered`: credentials issued and waiting for the
/// member to collect and accept them. `admitted`: accepted — on a sealed tier, the
/// member is in the room's group. `suspended`: admitted, but the room was archived
/// with `noAccess` (or scheduled for removal), so the room's host refuses the member's
/// credentials; on a sealed tier they are still in the room's group. Restored to
/// `admitted` with freshly issued credentials when the room leaves that state, and
/// never restored if it is removed. `removed`: an administrator removed them, or
/// withdrew their offer — archiving withdraws every open offer; on a sealed tier the
/// room has advanced past an admitted member.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const MemberStateV2(String value) {
  static const MemberStateV2 offered = MemberStateV2('offered');
  static const MemberStateV2 admitted = MemberStateV2('admitted');
  static const MemberStateV2 suspended = MemberStateV2('suspended');
  static const MemberStateV2 removed = MemberStateV2('removed');

  /// Every value this specification's schema permits.
  static const List<MemberStateV2> values = <MemberStateV2>[
    offered,
    admitted,
    suspended,
    removed
  ];
}

/// `RoomMember` with `MemberStateV2`, and `suspendedAt`.
class RoomMemberV2 {
  const RoomMemberV2({
    required this.member,
    required this.actions,
    required this.validUntil,
    required this.state,
    required this.offeredAt,
    this.admittedAt,
    this.removedAt,
    this.suspendedAt,
  });

  /// Read this payload from a decoded JSON object.
  factory RoomMemberV2.fromJson(Map<String, dynamic> json) => RoomMemberV2(
        member: json['member'] as String,
        actions: (json['actions'] as List<dynamic>)
            .map((e) => MemberAction(e as String))
            .toList(),
        validUntil: json['validUntil'] as String,
        state: MemberStateV2(json['state'] as String),
        offeredAt: json['offeredAt'] as String,
        admittedAt: json['admittedAt'] as String?,
        removedAt: json['removedAt'] as String?,
        suspendedAt: json['suspendedAt'] as String?,
      );

  final String member;
  final MemberActions actions;

  /// When the member's authority credential expires.
  final String validUntil;
  final MemberStateV2 state;
  final String offeredAt;
  final String? admittedAt;
  final String? removedAt;

  /// Present exactly when `state` is `suspended`.
  final String? suspendedAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'member': member,
        'actions': actions.map((e) => e.value).toList(),
        'validUntil': validUntil,
        'state': state.value,
        'offeredAt': offeredAt,
        if (admittedAt != null) 'admittedAt': admittedAt!,
        if (removedAt != null) 'removedAt': removedAt!,
        if (suspendedAt != null) 'suspendedAt': suspendedAt!,
      };
}

/// What vtc/rooms/memberships/list/0.2 returns: `RoomMembership` with `MemberStateV2`,
/// `suspendedAt`, and the room's own state, so that a member can tell a room that is
/// read-only, closed or going away from one they were removed from.
class RoomMembershipV2 {
  const RoomMembershipV2({
    required this.roomId,
    required this.host,
    required this.label,
    this.description,
    required this.visibility,
    required this.actions,
    required this.validUntil,
    required this.state,
    required this.offeredAt,
    this.admittedAt,
    this.removedAt,
    this.repeatAcceptUntil,
    this.suspendedAt,
    required this.roomState,
    this.roomAccess,
    this.purgeAt,
  });

  /// Read this payload from a decoded JSON object.
  factory RoomMembershipV2.fromJson(Map<String, dynamic> json) =>
      RoomMembershipV2(
        roomId: json['roomId'] as String,
        host: json['host'] as String,
        label: json['label'] as String,
        description: json['description'] as String?,
        visibility: Visibility(json['visibility'] as String),
        actions: (json['actions'] as List<dynamic>)
            .map((e) => MemberAction(e as String))
            .toList(),
        validUntil: json['validUntil'] as String,
        state: MemberStateV2(json['state'] as String),
        offeredAt: json['offeredAt'] as String,
        admittedAt: json['admittedAt'] as String?,
        removedAt: json['removedAt'] as String?,
        repeatAcceptUntil: json['repeatAcceptUntil'] as String?,
        suspendedAt: json['suspendedAt'] as String?,
        roomState: RoomState(json['roomState'] as String),
        roomAccess: json['roomAccess'] == null
            ? null
            : ArchiveAccess(json['roomAccess'] as String),
        purgeAt: json['purgeAt'] as String?,
      );

  final String roomId;

  /// The room's host: this community.
  final String host;
  final RoomLabel label;

  /// Absent when the room has none.
  final RoomDescription? description;
  final Visibility visibility;
  final MemberActions actions;

  /// When the member's authority credential expires.
  final String validUntil;
  final MemberStateV2 state;
  final String offeredAt;

  /// When the community recorded the admission. Present when `state` is `admitted`, and
  /// kept when it becomes `removed`.
  final String? admittedAt;

  /// Present exactly when `state` is `removed`.
  final String? removedAt;

  /// On an `attributed` or `private` room in state `admitted`: until when the community
  /// keeps the Welcome, so that a repeated vtc/rooms/offers/accept carrying the same
  /// KeyPackage is answered with it. Absent on an `open` room, in any other state, and
  /// once the community no longer keeps it. A surface finding the member admitted but
  /// the room absent from its key holder's rooms/keys/list finishes the acceptance
  /// before this time, and asks an administrator to re-admit the member after it.
  final String? repeatAcceptUntil;

  /// Present exactly when `state` is `suspended`.
  final String? suspendedAt;

  /// The room's state in its owner's lifecycle. `purging` is shown to members as
  /// `removalScheduled`: to them, the room is going away either way.
  final RoomState roomState;

  /// Present exactly when `roomState` is `archived` or `removalScheduled`.
  final ArchiveAccess? roomAccess;

  /// Present when `roomState` is `removalScheduled`: when the room's content is to be
  /// deleted.
  final String? purgeAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'roomId': roomId,
        'host': host,
        'label': label,
        if (description != null) 'description': description!,
        'visibility': visibility.value,
        'actions': actions.map((e) => e.value).toList(),
        'validUntil': validUntil,
        'state': state.value,
        'offeredAt': offeredAt,
        if (admittedAt != null) 'admittedAt': admittedAt!,
        if (removedAt != null) 'removedAt': removedAt!,
        if (repeatAcceptUntil != null) 'repeatAcceptUntil': repeatAcceptUntil!,
        if (suspendedAt != null) 'suspendedAt': suspendedAt!,
        'roomState': roomState.value,
        if (roomAccess != null) 'roomAccess': roomAccess!.value,
        if (purgeAt != null) 'purgeAt': purgeAt!,
      };
}
